import 'package:flutter/material.dart';

import '../../data/mission_catalog.dart';
import '../../models/lab_model.dart';
import '../../models/mission_model.dart';
import '../../services/mission_planning_service.dart';
import '../../services/mission_service.dart';
import 'mission_detail_screen.dart';
import 'mission_widgets.dart';

/// The Mission Mode setup wizard.
///
/// Everything the student answers here is a plan input. The mission itself is
/// generated by `MissionPlanningService`, which works offline and only links to
/// Study Nova content that already exists.
class MissionCreateScreen extends StatefulWidget {
  const MissionCreateScreen({super.key});

  @override
  State<MissionCreateScreen> createState() => _MissionCreateScreenState();
}

class _MissionCreateScreenState extends State<MissionCreateScreen> {
  final PageController _pageController = PageController();
  final MissionService _missionService = MissionService.instance;

  final TextEditingController _titleController = TextEditingController();
  final TextEditingController _customSubjectController =
      TextEditingController();
  final TextEditingController _customTopicController = TextEditingController();
  final TextEditingController _customExamController = TextEditingController();
  final TextEditingController _customMinutesController =
      TextEditingController();

  MissionSetup _setup = const MissionSetup();
  final Set<String> _subjects = <String>{};
  final List<String> _topics = <String>[];

  int _step = 0;
  bool _isCreating = false;
  bool _useAi = false;

  static const int _stepCount = 8;

  @override
  void dispose() {
    _pageController.dispose();
    _titleController.dispose();
    _customSubjectController.dispose();
    _customTopicController.dispose();
    _customExamController.dispose();
    _customMinutesController.dispose();
    super.dispose();
  }

  bool get _isLastStep => _step == _stepCount - 1;

  /// Validation for the current step, so the wizard never blocks the student
  /// for no reason and never creates an empty mission.
  String? _validationError() {
    switch (_step) {
      case 0:
        if (_titleController.text.trim().isEmpty) {
          return 'Give your mission a name, for example "Class 10 Science Mastery".';
        }
        return null;
      case 2:
        if (_subjects.isEmpty && _customSubjectController.text.trim().isEmpty) {
          return 'Pick at least one subject, or type your own.';
        }
        return null;
      case 3:
        if (_setup.customTargetDate != null &&
            _setup.customTargetDate!.isBefore(DateTime.now())) {
          return 'Pick a target date in the future.';
        }
        return null;
      default:
        return null;
    }
  }

  void _next() {
    final error = _validationError();
    if (error != null) {
      _showMessage(error);
      return;
    }
    if (_isLastStep) {
      _create();
      return;
    }
    setState(() => _step++);
    _pageController.animateToPage(
      _step,
      duration: const Duration(milliseconds: 250),
      curve: Curves.easeOut,
    );
  }

  void _back() {
    if (_step == 0) {
      Navigator.of(context).pop();
      return;
    }
    setState(() => _step--);
    _pageController.animateToPage(
      _step,
      duration: const Duration(milliseconds: 250),
      curve: Curves.easeOut,
    );
  }

  Future<void> _create() async {
    final error = _validationError();
    if (error != null) {
      _showMessage(error);
      return;
    }

    final subjects = <String>{
      ..._subjects,
      if (_customSubjectController.text.trim().isNotEmpty)
        _customSubjectController.text.trim(),
    };
    final topics = <String>[
      ..._topics,
      ..._customTopicController.text
          .split(RegExp(r'[,\n]'))
          .map((topic) => topic.trim())
          .where((topic) => topic.isNotEmpty),
    ];

    final hasCustomTarget =
        _setup.customTargetDate != null &&
        _setup.customTargetDate!.isAfter(DateTime.now());

    final setup = _setup.copyWith(
      title: _titleController.text.trim(),
      subjects: subjects.toList(),
      topics: topics,
      clearCustomTargetDate: !hasCustomTarget,
    );

    setState(() => _isCreating = true);
    final result = await _missionService.createMission(setup, useAi: _useAi);
    if (!mounted) return;
    setState(() => _isCreating = false);

    if (result.notes.isNotEmpty) {
      _showMessage(result.notes.first, long: true);
    }

    if (!mounted) return;
    Navigator.of(context).pushReplacement(
      MaterialPageRoute(
        builder: (_) => MissionDetailScreen(missionId: result.mission.id),
      ),
    );
  }

  void _showMessage(String message, {bool long = false}) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        duration: Duration(seconds: long ? 7 : 4),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final stepTitles = const <String>[
      'Mission name',
      'Learning goal',
      'Subjects & topics',
      'Target date',
      'Daily study time',
      'Current level',
      'Learning preference',
      'Exam target',
    ];

    return Scaffold(
      appBar: AppBar(
        title: const Text('Create New Mission'),
        centerTitle: true,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: _isCreating ? null : _back,
        ),
      ),
      body: MissionPage(
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 16, 20, 0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Step ${_step + 1} of $_stepCount · ${stepTitles[_step]}',
                    style: Theme.of(context).textTheme.titleSmall?.copyWith(
                      fontWeight: FontWeight.w700,
                      color: Colors.blue.shade700,
                    ),
                  ),
                  const SizedBox(height: 8),
                  ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: LinearProgressIndicator(
                      value: (_step + 1) / _stepCount,
                      minHeight: 6,
                      backgroundColor: Colors.grey.shade200,
                    ),
                  ),
                ],
              ),
            ),
            Expanded(
              child: PageView(
                controller: _pageController,
                physics: const NeverScrollableScrollPhysics(),
                children: [
                  _buildNameStep(),
                  _buildGoalStep(),
                  _buildSubjectStep(),
                  _buildDateStep(),
                  _buildTimeStep(),
                  _buildLevelStep(),
                  _buildPreferenceStep(),
                  _buildExamStep(),
                ],
              ),
            ),
            Container(
              padding: const EdgeInsets.fromLTRB(20, 12, 20, 20),
              decoration: BoxDecoration(
                color: Colors.white,
                border: Border(top: BorderSide(color: Colors.grey.shade300)),
              ),
              child: Row(
                children: [
                  if (_step > 0)
                    Expanded(
                      child: OutlinedButton(
                        onPressed: _isCreating ? null : _back,
                        child: const Text('Back'),
                      ),
                    ),
                  if (_step > 0) const SizedBox(width: 12),
                  Expanded(
                    flex: 2,
                    child: FilledButton.icon(
                      onPressed: _isCreating ? null : _next,
                      icon: Icon(
                        _isCreating
                            ? Icons.hourglass_top
                            : _isLastStep
                            ? Icons.flag
                            : Icons.arrow_forward,
                      ),
                      label: Text(
                        _isCreating
                            ? 'Creating mission...'
                            : _isLastStep
                            ? 'Create Mission'
                            : 'Next',
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ---------------------------------------------------------------------------
  // Steps
  // ---------------------------------------------------------------------------

  Widget _buildNameStep() {
    const suggestions = <String>[
      'Class 10 Science Mastery',
      'UPSC History Preparation',
      'Master General Science in 21 Days',
    ];

    return _stepScaffold(
      title: 'What is this mission called?',
      subtitle:
          'Mission Mode turns one clear goal into a day-by-day learning journey.',
      children: [
        TextField(
          controller: _titleController,
          textCapitalization: TextCapitalization.words,
          onChanged: (_) => setState(() {}),
          decoration: const InputDecoration(
            labelText: 'Mission name',
            hintText: 'Class 10 Science Mastery',
            border: OutlineInputBorder(),
          ),
        ),
        const SizedBox(height: 16),
        Text(
          'Examples',
          style: Theme.of(
            context,
          ).textTheme.bodySmall?.copyWith(color: Colors.grey.shade600),
        ),
        const SizedBox(height: 8),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: suggestions
              .map(
                (suggestion) => ActionChip(
                  label: Text(suggestion),
                  onPressed: () {
                    _titleController.text = suggestion;
                    setState(() {});
                  },
                ),
              )
              .toList(),
        ),
      ],
    );
  }

  Widget _buildGoalStep() {
    return _stepScaffold(
      title: 'What do you want to achieve?',
      subtitle: 'Your goal shapes how the daily tasks are balanced.',
      children: [
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: MissionGoal.values
              .map(
                (goal) => ChoiceChip(
                  label: Text(goal.label),
                  selected: _setup.goal == goal,
                  onSelected: (_) =>
                      setState(() => _setup = _setup.copyWith(goal: goal)),
                ),
              )
              .toList(),
        ),
      ],
    );
  }

  Widget _buildSubjectStep() {
    return _stepScaffold(
      title: 'Which subjects and topics?',
      subtitle:
          'Study Nova looks for courses and Study Nova Labs that match what '
          'you pick, so the mission opens real content.',
      children: [
        Text(
          'Subjects',
          style: Theme.of(
            context,
          ).textTheme.titleSmall?.copyWith(fontWeight: FontWeight.w700),
        ),
        const SizedBox(height: 8),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: MissionCatalog.subjects
              .map(
                (subject) => FilterChip(
                  label: Text(subject.name),
                  selected: _subjects.contains(subject.name),
                  onSelected: (selected) => setState(() {
                    if (selected) {
                      _subjects.add(subject.name);
                    } else {
                      _subjects.remove(subject.name);
                    }
                  }),
                ),
              )
              .toList(),
        ),
        const SizedBox(height: 16),
        TextField(
          controller: _customSubjectController,
          onChanged: (_) => setState(() {}),
          decoration: const InputDecoration(
            labelText: 'Add your own subject',
            hintText: 'e.g. Robotics',
            border: OutlineInputBorder(),
          ),
        ),
        const SizedBox(height: 20),
        Text(
          'Topics (optional)',
          style: Theme.of(
            context,
          ).textTheme.titleSmall?.copyWith(fontWeight: FontWeight.w700),
        ),
        const SizedBox(height: 8),
        Text(
          'Pick a few, or leave this empty to use the default topics for your '
          'subject.',
          style: Theme.of(
            context,
          ).textTheme.bodySmall?.copyWith(color: Colors.grey.shade600),
        ),
        const SizedBox(height: 8),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: MissionCatalog.defaultTopicsFor(_subjects.toList())
              .map(
                (topic) => FilterChip(
                  label: Text(topic),
                  selected: _topics.contains(topic),
                  onSelected: (selected) => setState(() {
                    if (selected) {
                      _topics.add(topic);
                    } else {
                      _topics.remove(topic);
                    }
                  }),
                ),
              )
              .toList(),
        ),
        const SizedBox(height: 12),
        TextField(
          controller: _customTopicController,
          decoration: const InputDecoration(
            labelText: 'Add your own topics',
            hintText: 'Comma separated, e.g. Optics, Refraction',
            border: OutlineInputBorder(),
          ),
        ),
      ],
    );
  }

  Widget _buildDateStep() {
    return _stepScaffold(
      title: 'When do you want to finish?',
      subtitle: 'Mission Mode spreads your topics across the days you choose.',
      children: [
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: MissionCatalog.durationOptions
              .map(
                (days) => ChoiceChip(
                  label: Text('$days days'),
                  selected:
                      _setup.customTargetDate == null &&
                      _setup.durationDays == days,
                  onSelected: (_) => setState(
                    () => _setup = _setup.copyWith(
                      durationDays: days,
                      clearCustomTargetDate: true,
                    ),
                  ),
                ),
              )
              .toList(),
        ),
        const SizedBox(height: 20),
        OutlinedButton.icon(
          onPressed: () async {
            final picked = await showDatePicker(
              context: context,
              firstDate: DateTime.now().add(const Duration(days: 1)),
              lastDate: DateTime.now().add(const Duration(days: 365)),
              initialDate: DateTime.now().add(const Duration(days: 14)),
            );
            if (picked == null) return;
            setState(() => _setup = _setup.copyWith(customTargetDate: picked));
          },
          icon: const Icon(Icons.event),
          label: Text(
            _setup.customTargetDate == null
                ? 'Pick a custom target date'
                : 'Target date: ${_formatDate(_setup.customTargetDate!)}',
          ),
        ),
        if (_setup.customTargetDate != null) ...[
          const SizedBox(height: 10),
          TextButton.icon(
            onPressed: () => setState(
              () => _setup = _setup.copyWith(clearCustomTargetDate: true),
            ),
            icon: const Icon(Icons.close, size: 18),
            label: const Text('Use a fixed number of days instead'),
          ),
        ],
        const SizedBox(height: 20),
        Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: Colors.blue.shade50,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Row(
            children: [
              const Icon(Icons.info_outline, color: Colors.blue),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  _setup.customTargetDate == null
                      ? '${_setup.resolvedDurationDays} day mission'
                      : '${_setup.resolvedDurationDays} day mission, finishing on ${_formatDate(_setup.resolvedTargetDate)}',
                  style: Theme.of(context).textTheme.bodySmall,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildTimeStep() {
    return _stepScaffold(
      title: 'How much time can you study each day?',
      subtitle: 'Daily tasks are sized to fit this time.',
      children: [
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: MissionCatalog.dailyStudyOptions
              .map(
                (minutes) => ChoiceChip(
                  label: Text(_minutesLabel(minutes)),
                  selected:
                      _customMinutesController.text.trim().isEmpty &&
                      _setup.dailyStudyMinutes == minutes,
                  onSelected: (_) => setState(
                    () => _setup = _setup.copyWith(dailyStudyMinutes: minutes),
                  ),
                ),
              )
              .toList(),
        ),
        const SizedBox(height: 20),
        TextField(
          controller: _customMinutesController,
          keyboardType: TextInputType.number,
          onChanged: (value) {
            final minutes = int.tryParse(value);
            if (minutes == null || minutes <= 0) return;
            setState(
              () => _setup = _setup.copyWith(
                dailyStudyMinutes: minutes.clamp(5, 480),
              ),
            );
          },
          decoration: const InputDecoration(
            labelText: 'Custom minutes per day',
            hintText: 'e.g. 75',
            border: OutlineInputBorder(),
          ),
        ),
        const SizedBox(height: 16),
        MissionBadge(
          label:
              'About ${formatStudyMinutes(_setup.dailyStudyMinutes)} per day',
          color: kMissionPrimary,
          icon: Icons.schedule,
        ),
      ],
    );
  }

  Widget _buildLevelStep() {
    return _stepScaffold(
      title: 'Where are you starting from?',
      subtitle: 'Your level decides how much guidance each task carries.',
      children: [
        ...LabDifficulty.values.map(
          (level) => Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: ChoiceChip(
              label: Padding(
                padding: const EdgeInsets.symmetric(vertical: 6),
                child: Text(
                  '${level.label} — ${_levelDescription(level)}',
                  style: const TextStyle(fontWeight: FontWeight.w600),
                ),
              ),
              selected: _setup.level == level,
              onSelected: (_) =>
                  setState(() => _setup = _setup.copyWith(level: level)),
            ),
          ),
        ),
      ],
    );
  }

  String _levelDescription(LabDifficulty level) {
    switch (level) {
      case LabDifficulty.beginner:
        return 'I am starting from the basics';
      case LabDifficulty.intermediate:
        return 'I know the basics and want depth';
      case LabDifficulty.advanced:
        return 'I want fast, exam-level coverage';
    }
  }

  Widget _buildPreferenceStep() {
    return _stepScaffold(
      title: 'How do you like to learn?',
      subtitle: 'The plan mixes lessons, practice and quizzes accordingly.',
      children: [
        ...MissionPreference.values.map(
          (preference) => Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: ChoiceChip(
              label: Text(preference.label),
              selected: _setup.preference == preference,
              onSelected: (_) => setState(
                () => _setup = _setup.copyWith(preference: preference),
              ),
            ),
          ),
        ),
        const SizedBox(height: 12),
        Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: Colors.indigo.shade50,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Row(
            children: [
              const Icon(Icons.route, color: Colors.indigo),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  'Mixed is recommended: it combines lessons, quizzes and '
                  'practice every day.',
                  style: Theme.of(context).textTheme.bodySmall,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildExamStep() {
    final canUseAi = MissionPlanningService.instance.isAiAvailable;

    return _stepScaffold(
      title: 'Which exam is this mission for?',
      subtitle:
          'Optional. The exam target only changes the plan — it never adds '
          'exam content that is not already in Study Nova.',
      children: [
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: MissionExamTarget.values
              .map(
                (target) => ChoiceChip(
                  label: Text(target.label),
                  selected: _setup.examTarget == target,
                  onSelected: (_) => setState(
                    () => _setup = _setup.copyWith(examTarget: target),
                  ),
                ),
              )
              .toList(),
        ),
        if (_setup.examTarget == MissionExamTarget.custom) ...[
          const SizedBox(height: 16),
          TextField(
            controller: _customExamController,
            onChanged: (value) => setState(
              () => _setup = _setup.copyWith(customExamTarget: value),
            ),
            decoration: const InputDecoration(
              labelText: 'Exam name',
              hintText: 'e.g. Board exams',
              border: OutlineInputBorder(),
            ),
          ),
        ],
        if (canUseAi) ...[
          const SizedBox(height: 20),
          SwitchListTile(
            value: _useAi,
            onChanged: (value) => setState(() => _useAi = value),
            title: const Text('Use AI to refine the plan'),
            subtitle: const Text(
              'Optional. The plan is built on your device; AI only improves the '
              'wording. If AI is unavailable the same plan is used.',
            ),
          ),
        ],
        const SizedBox(height: 20),
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            border: Border.all(color: Colors.grey.shade300),
            borderRadius: BorderRadius.circular(12),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Mission summary',
                style: Theme.of(
                  context,
                ).textTheme.titleSmall?.copyWith(fontWeight: FontWeight.w700),
              ),
              const SizedBox(height: 10),
              Text(
                '• ${_titleController.text.trim().isEmpty ? 'Untitled mission' : _titleController.text.trim()}\n'
                '• Goal: ${_setup.goal.label}\n'
                '• Subjects: ${_subjects.isEmpty && _customSubjectController.text.trim().isEmpty ? 'None picked yet' : _subjectPreview()}\n'
                '• Length: ${_setup.resolvedDurationDays} days\n'
                '• Daily time: ${formatStudyMinutes(_setup.dailyStudyMinutes)}\n'
                '• Level: ${_setup.level.label}\n'
                '• Preference: ${_setup.preference.label}',
                style: Theme.of(context).textTheme.bodySmall,
              ),
            ],
          ),
        ),
      ],
    );
  }

  String _subjectPreview() {
    final parts = <String>{
      ..._subjects,
      if (_customSubjectController.text.trim().isNotEmpty)
        _customSubjectController.text.trim(),
    };
    return parts.join(', ');
  }

  Widget _stepScaffold({
    required String title,
    required String subtitle,
    required List<Widget> children,
  }) {
    return ListView(
      padding: const EdgeInsets.fromLTRB(20, 20, 20, 24),
      children: [
        Text(
          title,
          style: Theme.of(
            context,
          ).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 8),
        Text(
          subtitle,
          style: Theme.of(
            context,
          ).textTheme.bodyMedium?.copyWith(color: Colors.grey.shade700),
        ),
        const SizedBox(height: 20),
        ...children,
      ],
    );
  }

  String _minutesLabel(int minutes) {
    if (minutes < 60) return '$minutes minutes';
    if (minutes == 60) return '1 hour';
    final hours = minutes ~/ 60;
    final rest = minutes % 60;
    return rest == 0 ? '$hours hours' : '$hours h $rest m';
  }

  String _formatDate(DateTime date) => '${date.day}/${date.month}/${date.year}';
}
